function spark(points, { large = false, label = 'Price history', timestamps = [], color = 'var(--text)', id = 'spark' } = {}) {
  const clean = points.map((v, i) => ({ v, t: timestamps[i] })).filter(p => finite(p.v));
  if (clean.length < 2) return `<div class="chart-empty">Price history unavailable</div>`;
  const w = large ? 900 : 170, h = large ? 260 : 60, pad = large ? 18 : 3;
  const vals = clean.map(p => p.v), min = Math.min(...vals), max = Math.max(...vals), span = max - min || Math.max(1, max * .01);
  const pts = clean.map((p, i) => `${pad + i / (clean.length - 1) * (w - pad * 2)},${h - pad - (p.v - min) / span * (h - pad * 2)}`);
  const d = 'M' + pts.join(' L');
  return `<svg class="${large ? 'price-chart' : 'sparkline'}" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(label)}"><title>${esc(label)} · ${num(vals[0], 2)} to ${num(vals.at(-1), 2)}</title><defs><linearGradient id="${id}" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="${color}" stop-opacity=".19"/><stop offset="100%" stop-color="${color}" stop-opacity="0"/></linearGradient></defs>${large ? [0, 1, 2, 3].map(i => `<path d="M0 ${pad + i * (h - 2 * pad) / 3}H${w}" stroke="var(--line)" stroke-dasharray="3 6"/>`).join('') : ''}<path d="${d} L${w - pad},${h} L${pad},${h}Z" fill="url(#${id})"/><path d="${d}" fill="none" stroke="${large ? color : 'var(--muted)'}" stroke-width="${large ? 2.5 : 2}" vector-effect="non-scaling-stroke" stroke-linejoin="round"/>${large ? clean.filter((_, i) => i % Math.max(1, Math.floor(clean.length / 70)) === 0).map(p => { const i = clean.indexOf(p); return `<circle cx="${pad + i / (clean.length - 1) * (w - pad * 2)}" cy="${h - pad - (p.v - min) / span * (h - pad * 2)}" r="8" fill="transparent"><title>${p.t ? date(new Date(p.t * 1000).toISOString()) + ': ' : ''}${num(p.v, 2)}</title></circle>`; }).join('') : ''}</svg>${large ? `<div class="chart-axis"><span>${clean[0].t ? date(new Date(clean[0].t * 1000).toISOString()) : 'Session open'}</span><span>Low ${num(min, 2)} · High ${num(max, 2)}</span><span>${clean.at(-1).t ? date(new Date(clean.at(-1).t * 1000).toISOString()) : 'Latest'}</span></div>` : ''}`;
}
