function companyCell(r) { return `<a class="company-cell" data-company="${esc(r.sym)}" href="${companyURL(r.sym)}"><span class="company-avatar hue-${r.sym.charCodeAt(0) % 5}">${esc(r.sym.slice(0, 2))}</span><span><strong>${esc(r.sym)}</strong><small>${esc(r.name)}</small></span></a>`; }
function rowTable(rows, compact = false) {
  const rule = r => trend(r) === 'Uptrend' ? 'The close is above the 50-day average, and the 50-day is above the 200-day.' : trend(r) === 'Downtrend' ? 'The close is below the 50-day average, and the 50-day is below the 200-day.' : trend(r) === 'Unknown' ? 'An average or price is missing. No trend classification is assigned.' : 'The price and moving averages are not consistently ordered. The evidence is mixed.';
  const history = r => `<div class="row-spark" data-spark="${esc(r.sym)}"><span class="spark-unavailable">History loading…</span></div>`;
  const explanation = r => `<details class="row-reason"><summary>Why this trend?</summary><p>${rule(r)}</p></details>`;
  return `<div class="table-scroll research-table"><table><thead><tr><th scope="col">Company</th><th scope="col">60 sessions</th><th scope="col">Close</th><th scope="col">1 day</th>${compact ? '' : '<th scope="col">3 months</th><th scope="col">P/E</th><th scope="col">ROCE</th><th scope="col">Trend</th>'}<th scope="col"><span class="sr-only">Follow</span></th></tr></thead><tbody>${rows.map(r=>`<tr><td>${companyCell(r)}${compact?'':explanation(r)}</td><td>${history(r)}</td><td class="numeric">${money(r.price)}</td><td>${badge(r.r1d)}</td>${compact?'':`<td>${badge(r.r3m)}</td><td class="numeric">${num(r.pe)}</td><td class="numeric">${finite(r.roce)?num(r.roce)+'%':'—'}</td><td><span class="pill trend-chip ${trend(r)==='Uptrend'?'positive':trend(r)==='Downtrend'?'negative':''}">${trend(r)}</span></td>`}<td>${watchButton(r.sym,true)}</td></tr>`).join('')}</tbody></table></div><div class="research-cards">${rows.map(r=>`<article class="research-mobile-card"><div class="mobile-card-head">${companyCell(r)}${watchButton(r.sym,true)}</div><div class="mobile-card-price"><strong>${money(r.price)}</strong>${badge(r.r1d)}${history(r)}</div><div class="mobile-card-facts"><span class="pill trend-chip">${trend(r)}</span><span>ROCE <b>${finite(r.roce)?num(r.roce)+'%':'—'}</b></span><span>P/E <b>${num(r.pe)}</b></span></div>${explanation(r)}</article>`).join('')}</div>`;
}
