document.addEventListener('input', event => {
  if (event.target.closest('#note-form')) { const form = event.target.closest('#note-form'); drafts[form.dataset.symbol] = Object.fromEntries(new FormData(form)); }
  if (event.target.id === 'global-search') searchResults(event.target.value.trim());
  if (event.target.id === 'filter-query') { state.filter.query = event.target.value; state.page = 1; render({ preserveFocus: true }); }
});
document.addEventListener('change', async event => {
  if(event.target.id==='field-axis'){editionAxis=event.target.value;render();$('#advanced-research').open=true;$('#evidence-explorer').open=true;$('#field-axis')?.focus({preventScroll:true});}
  if(event.target.id==='census-score'){censusKey=event.target.value;render();$('#advanced-research').open=true;$('#census-score')?.focus({preventScroll:true});}
  if(event.target.id==='market-cadence'){const n=Number(event.target.value);if([60,120,180].includes(n)){quoteCadence=n;try{localStorage.setItem('apexpro:quote-cadence',String(n));}catch{}quotePoller.restart();}}
  if(event.target.id==='rsi-period'){state.rsiPeriod=Number(event.target.value);render();$('#rsi-period')?.focus();}
  if(event.target.dataset.homeVisible) { const layout=home.layouts[home.profile],k=event.target.dataset.homeVisible;layout.hidden=event.target.checked?layout.hidden.filter(x=>x!==k):[...new Set([...layout.hidden,k])];saveHome();renderHomeEditor();$('.home-editor [data-home-visible="'+k+'"]')?.focus(); }
  if(event.target.dataset.homeSize) { const k=event.target.dataset.homeSize;home.layouts[home.profile].sizes[k]=event.target.value;saveHome();renderHomeEditor();$('.home-editor [data-home-size="'+k+'"]')?.focus(); }
  if (event.target.id === 'sector-filter') { state.filter.sector = event.target.value; state.page = 1; render(); }
  if (event.target.id === 'sort-filter') { state.filter.sort = event.target.value; state.filter.direction = event.target.value === 'pe' ? 1 : -1; state.page = 1; render(); }
  if (event.target.id === 'import-file') { try { const file = event.target.files[0]; if (!file) return; if (file.size > 3000000) throw new Error(); const raw = JSON.parse(await file.text()); if (raw.schema !== 'apexpro-desk/1') throw new Error(); const incoming = normalizeDesk(raw); desk = { watch: [...new Set([...desk.watch, ...incoming.watch])].slice(0, 200), notes: { ...incoming.notes, ...desk.notes }, snapshots: { ...incoming.snapshots, ...desk.snapshots }, conditions: { ...incoming.conditions, ...desk.conditions } }; researchTrail=mergeTrail(researchTrail,raw.researchTrail);saveTrail();saveDesk(); render(); toast('Backup imported. Existing notes were kept where both copies had a note.'); } catch { toast('This is not a valid ApexPro backup. Your existing research is unchanged.'); } }
});
document.addEventListener('submit', event => {
  if(event.target.id==='condition-form') { event.preventDefault();const sym=event.target.dataset.symbol,form=new FormData(event.target),target=Number(form.get('target')),direction=form.get('direction');if(!finite(target)||target<.01||target>1e9||!['above','below'].includes(direction))return;if(!desk.conditions[sym]&&Object.keys(desk.conditions).length>=200){toast('You can save up to 200 conditions.');return;}desk.conditions[sym]={target,direction};const saved=saveDesk();researchTrail=observationEvents(state.rows,desk,researchTrail);saveTrail();render();if(saved)toast('Price condition saved. Check it in My Desk.');return; }
  if (event.target.id !== 'note-form') return; event.preventDefault(); const s = event.target.dataset.symbol, values = Object.fromEntries(new FormData(event.target)); desk.notes[s] = { ...values, updated: new Date().toISOString() }; delete drafts[s]; if (!desk.watch.includes(s)) desk.watch.push(s); const row = state.rows.find(r => r.sym === s); if (row && !desk.snapshots[s]) desk.snapshots[s] = snapshot(row); if (saveDesk()){recordTrail('note',s,'Research note saved','Your thesis and review date were updated. Note contents remain in My Desk.');toast('Research saved on this device');} shell(); });
document.addEventListener('keydown', event => {
  if (!event.metaKey && !event.ctrlKey && !event.altKey && /^[1-4]$/.test(event.key) && !event.target.closest?.('input,textarea,select,[contenteditable],dialog')) { const t=navItems[+event.key-1]; if (t) { location.hash='#/'+t[0]; } }
  if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === 'k') { event.preventDefault(); if (!$('#search-dialog').open) openSearch(); }
  if (event.target.id === 'global-search' && (event.key === 'ArrowDown' || event.key === 'Enter')) { event.preventDefault(); const first = $('#search-results button'); if (event.key === 'Enter') first?.click(); else first?.focus(); }
  if (event.target.classList.contains('search-result') && ['ArrowDown', 'ArrowUp'].includes(event.key)) { event.preventDefault(); const items=[...$('#search-results').querySelectorAll('button')],i=items.indexOf(event.target),next=(i+(event.key==='ArrowDown'?1:-1)+items.length)%items.length;items[next]?.focus(); }
});
$('#search-dialog').addEventListener('click', e => { if (e.target === $('#search-dialog')) { const r = e.target.getBoundingClientRect(); if (e.clientX < r.left || e.clientX > r.right || e.clientY < r.top || e.clientY > r.bottom) e.target.close(); } });
let previousRoute = route()[0], discoverScroll = 0;
