window.addEventListener('hashchange', async () => { if (previousRoute === 'discover') discoverScroll = window.scrollY; const next = route()[0]; previousRoute = next; await routeTransition(()=>{render();window.scrollTo(0,next==='discover'?discoverScroll:0);$('#main').focus({preventScroll:true});},noMotion(display)); loadCompany(); if(next==='')quotePoller.restart(Date.now()-quoteChecked>=quoteCadence*1000);else quotePoller.stop(); });
window.addEventListener('beforeinstallprompt', e => { e.preventDefault(); installPrompt = e; });
